// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public {
        c = new DepositLog();
        vm.prank(address(0));
        c.setApprovedLogger(address(0x1234), true);
    }
    function testFuzz_property(address logger) public {
        vm.assume(logger != address(0));
        vm.prank(address(0));
        c.setApprovedLogger(logger, true);

        vm.prank(logger);
        bool result = c.logCreated(address(0xdead));
        assertTrue(result);
    }
}
